SELECT salariesfrance_2.codes_rome_destination AS codes_rome_destination,   salariesfrance_2.description AS description,   salariesfrance_2.rome_lib_destination AS rome_lib_destination,   salariesfrance_2.types_mobilite AS types_mobilite FROM salariesfrance_2 WHERE (salariesfrance_2.appellation = 'Manutentionnaire') GROUP BY salariesfrance_2.codes_rome_destination,   salariesfrance_2.description,   salariesfrance_2.rome_lib_destination,   salariesfrance_2.types_mobilite;
